SELECT "investor_name" AS "investor_name", "investor_gp_id" AS "investor_id", "currency" AS "currency", SUM(TRY_CAST("order_allocation" AS DOUBLE)) AS "total_allocation" FROM "bds_dg_oraas"."dgstream"."vw_order_detail" WHERE "product" = __P_f0__ AND UPPER("product_class") LIKE UPPER(__P_f1__) AND "pricing_ts" >= __P_f2__ AND "pricing_ts" < __P_f3__ GROUP BY "investor_name", "investor_gp_id", "currency" ORDER BY "total_allocation" DESC, "investor_name" ASC LIMIT 5
